package br.com.onda;
import android.app.*;import android.content.*;import android.os.BatteryManager;import android.view.*;import android.widget.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
public class BatteryIndicatorTest {
 private Intent reading(int level,int scale,int status){return new Intent(Intent.ACTION_BATTERY_CHANGED).putExtra(BatteryManager.EXTRA_LEVEL,level).putExtra(BatteryManager.EXTRA_SCALE,scale).putExtra(BatteryManager.EXTRA_STATUS,status);}
 @Test public void percentageHandlesScaleFullUnknownAndCharging(){
  Instrumentation ins=getInstrumentation();Activity a=ins.startActivitySync(new Intent(ins.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  try{ins.runOnMainSync(()->{BatteryIndicator b=new BatteryIndicator(a);b.accept(reading(3,4,BatteryManager.BATTERY_STATUS_CHARGING));assertEquals("75%",b.badge.getText().toString());assertTrue(b.badge.getContentDescription().toString().contains("Carregando"));b.accept(reading(100,100,BatteryManager.BATTERY_STATUS_FULL));assertEquals("100%",b.badge.getText().toString());assertTrue(b.badge.getContentDescription().toString().contains("Carga completa"));b.accept(reading(-1,0,BatteryManager.BATTERY_STATUS_UNKNOWN));assertEquals("—%",b.badge.getText().toString());b.accept(reading(0,100,BatteryManager.BATTERY_STATUS_DISCHARGING));assertEquals("0%",b.badge.getText().toString());});}finally{ins.runOnMainSync(a::finish);}
 }
 @Test public void realSystemValueAndLargeDisplayStopWithActivity()throws Exception{
  Instrumentation ins=getInstrumentation();Context c=ins.getTargetContext();MainActivity a=(MainActivity)ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.lang.reflect.Field f=MainActivity.class.getDeclaredField("battery");f.setAccessible(true);BatteryIndicator b=(BatteryIndicator)f.get(a);
  try{ins.waitForIdleSync();ins.runOnMainSync(()->{assertTrue(b.isListening());Intent current=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));assertNotNull(current);int level=current.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=current.getIntExtra(BatteryManager.EXTRA_SCALE,-1);assertTrue(b.badge.getText().toString().contains(Math.round(level*100.0/scale)+"%"));assertTrue(b.badge.isShown());b.badge.performClick();b.accept(reading(37,100,BatteryManager.BATTERY_STATUS_DISCHARGING));});ins.waitForIdleSync();java.lang.reflect.Field d=BatteryIndicator.class.getDeclaredField("dialog");d.setAccessible(true);AlertDialog dialog=(AlertDialog)d.get(b);assertNotNull(dialog);ins.runOnMainSync(()->{TextView large=dialog.getWindow().getDecorView().findViewWithTag("onda-battery-large");assertEquals("37%",large.getText().toString());assertTrue(large.getHeight()>b.badge.getHeight());});android.graphics.Bitmap shot=ins.getUiAutomation().takeScreenshot();try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(c.getFilesDir(),"battery-large.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}ins.runOnMainSync(a::finish);ins.waitForIdleSync();assertFalse(b.isListening());assertFalse(dialog.isShowing());}finally{if(!a.isFinishing())ins.runOnMainSync(a::finish);}
 }
}
